#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <string.h>
#include <errno.h>

#define STACK_SIZE 512
#define MSG_SIZE 16

K_MBOX_DEFINE(test_mbox);

struct k_msg {
    uint32_t id;
    uint8_t data[MSG_SIZE];
};

K_THREAD_STACK_DEFINE(sender_stack, STACK_SIZE);
K_THREAD_STACK_DEFINE(receiver_stack, STACK_SIZE);

static struct k_thread sender_thread_data;
static struct k_thread receiver_thread_data;

static struct k_msg tx_msg;
static struct k_msg rx_msg;

static void sender_entry(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    tx_msg.id = 0xDEADBEEF;
    memcpy(tx_msg.data, "Hello Mbox!", 12);

    k_mbox_put(&test_mbox, &tx_msg, K_NO_WAIT);
    k_thread_suspend(k_current_get());
}

static void receiver_entry(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    k_mbox_get(&test_mbox, &rx_msg, K_FOREVER);
    k_thread_suspend(k_current_get());
}

static void *mbox_setup(void)
{
    struct k_mbox_msg_t dummy_msg;
    /* Drain any pending messages from previous tests */
    while (k_mbox_get(&test_mbox, &dummy_msg, K_NO_WAIT) == 0) {
        /* Message drained, continue */
    }
    memset(&tx_msg, 0, sizeof(tx_msg));
    memset(&rx_msg, 0, sizeof(rx_msg));
    return NULL;
}

static void mbox_teardown(void *data)
{
    ARG_UNUSED(data);
    /* Threads created within a ZTEST_DMEM test function are typically
     * aborted by the ztest framework itself or expected to terminate.
     */
}

ZTEST_DMEM static void test_mbox_send_receive(void)
{
    k_tid_t sender_tid, receiver_tid;

    sender_tid = k_thread_create(&sender_thread_data, sender_stack,
                                 K_THREAD_STACK_SIZEOF(sender_stack),
                                 sender_entry, NULL, NULL, NULL,
                                 K_PRIO_PREEMPT(7), 0, K_NO_WAIT);

    receiver_tid = k_thread_create(&receiver_thread_data, receiver_stack,
                                   K_THREAD_STACK_SIZEOF(receiver_stack),
                                   receiver_entry, NULL, NULL, NULL,
                                   K_PRIO_PREEMPT(7), 0, K_NO_WAIT);

    k_thread_start(sender_tid);
    k_thread_start(receiver_tid);

    k_msleep(100); /* Give threads time to run */

    zassert_equal(tx_msg.id, rx_msg.id, "Message ID mismatch");
    zassert_mem_equal(tx_msg.data, rx_msg.data, 12, "Message data mismatch");
}

static void sender_timeout_entry(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    tx_msg.id = 0xCAFEBABE;
    memcpy(tx_msg.data, "Timeout Test", 12);

    int ret = k_mbox_put(&test_mbox, &tx_msg, K_MSEC(10));
    zassert_equal(ret, -EAGAIN, "Sender put should timeout");
    k_thread_suspend(k_current_get());
}

ZTEST_DMEM static void test_mbox_send_timeout(void)
{
    k_tid_t sender_tid;

    sender_tid = k_thread_create(&sender_thread_data, sender_stack,
                                 K_THREAD_STACK_SIZEOF(sender_stack),
                                 sender_timeout_entry, NULL, NULL, NULL,
                                 K_PRIO_PREEMPT(7), 0, K_NO_WAIT);

    k_thread_start(sender_tid);
    k_msleep(200); /* Give thread time to run and timeout */

    k_thread_abort(sender_tid);
}

static void receiver_timeout_entry(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    struct k_msg local_rx_msg;
    int ret = k_mbox_get(&test_mbox, &local_rx_msg, K_MSEC(10));
    zassert_equal(ret, -EAGAIN, "Receiver get should timeout");
    k_thread_suspend(k_current_get());
}

ZTEST_DMEM static void test_mbox_receive_timeout(void)
{
    k_tid_t receiver_tid;

    receiver_tid = k_thread_create(&receiver_thread_data, receiver_stack,
                                   K_THREAD_STACK_SIZEOF(receiver_stack),
                                   receiver_timeout_entry, NULL, NULL, NULL,
                                   K_PRIO_PREEMPT(7), 0, K_NO_WAIT);

    k_thread_start(receiver_tid);
    k_msleep(200); /* Give thread time to run and timeout */

    k_thread_abort(receiver_tid);
}

ZTEST_SUITE(mbox_usage, mbox_setup, mbox_teardown, NULL, NULL, NULL);
